-- Verificar CARLOS HUMBERTO com vencimento 2024-10-08
SELECT id, cliente, LEFT(vencimentoData,10) as venc, valorLiquido FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%CARLOS HUMBERTO%';

-- Verificar RONALDO ANTONIO com vencimento 2026-03-24
SELECT id, cliente, LEFT(vencimentoData,10) as venc, valorLiquido FROM accounts_receivable 
WHERE UPPER(cliente) LIKE '%RONALDO%' AND LEFT(vencimentoData,10) = '2026-03-24';
